-- Study Abroad country content, BATCH 13: Kyrgyzstan, Armenia, Azerbaijan, Bahrain, Kuwait.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('kyrgyzstan', 'armenia', 'azerbaijan', 'bahrain', 'kuwait'));
UPDATE countries SET why_title = 'Why study in Kyrgyzstan?', why_body = '<p>Kyrgyzstan is a low-cost destination in Central Asia, best known for English-medium medicine programmes in Bishkek and Osh, plus programmes at the American University of Central Asia.</p><ul><li>Low tuition for medicine and other fields</li><li>English-medium programmes at several universities</li><li>Low living costs</li><li>Mountain landscapes and outdoor life</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Most non-CIS students need an <strong>S-type study visa</strong>, which can be requested online through the Kyrgyz e-visa portal. Some students from visa-free countries must still register after arrival.</p><ul><li>Admission or invitation letter from the university</li><li>Passport, photographs and medical fitness certificate</li><li>Register with the authorities after arrival</li><li>Student visa holders may not work; graduates need a work visa and permit</li><li>A new state accreditation system for medical institutions began in 2026, and a September 2026 ministry order moved students from some unaccredited schools to accredited ones, so confirm accreditation before paying</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Kyrgyz embassy, the EduGate portal and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Admission for international students is moving through a national centre set up in 2026 (reported in Indian embassy advisories), so check the EduGate portal and your embassy before applying.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Passport copy and photographs</li><li>Medical fitness certificate</li><li>Entrance exam score for medicine where required (for example NEET for Indian applicants)</li><li>English proficiency proof for English-taught programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Reported fees conflict between sources.</p><ul><li>Minimum tuition on the admission platform was reported at US$3,000 (US$3,500 at KSMA), with compulsory health insurance of 11,910 KGS a year (Ministry of Health, April 2026)</li><li>Agency pages list about US$4,000 a year at KSMA and higher totals for some schools; treat these as unconfirmed</li><li>Osh and Jalal-Abad are generally cheaper than Bishkek</li><li>Living costs: about US$200-$400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-taught programmes; Russian or Kyrgyz may be needed for clinical training</li></ul>' WHERE slug = 'kyrgyzstan';
UPDATE countries SET why_title = 'Why study in Armenia?', why_body = '<p>Armenia offers low-cost, English-taught medicine and technical programmes in Yerevan, with a small, safe capital and a strong IT sector.</p><ul><li>English-taught medicine at Yerevan State Medical University</li><li>Low tuition and living costs</li><li>Growing IT and tech sector</li><li>Safe, welcoming environment</li></ul>', visa_title = 'Residence permit requirements', visa_body = '<p>Foreign students can get a <strong>temporary residence permit (TRP)</strong> on study grounds, renewable annually. A law firm reports that from 1 November 2026 (another source says 1 August) institutions must file student TRP applications through a new unified electronic platform.</p><ul><li>Enrolment in an Armenian institution</li><li>Fee: sources conflict (students reported exempt from the AMD 105,000 fee, or the fee rising to AMD 150,000 after November 2026)</li><li>Student TRPs cannot be converted to permanent residence</li><li>Check visa exemption for your nationality at mfa.am</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Armenian Migration and Citizenship Service and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Foreign applicants to Yerevan State Medical University for 2026-27 applied through fs.emis.am from 22 June to 30 September 2026; the next cycle will follow a similar calendar (confirm).</p><ul><li>Secondary school certificate</li><li>Passport copy and photographs</li><li>Medical certificate</li><li>English proficiency proof</li><li>Entrance exam or interview for medicine</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees conflict between the university and aggregator sites.</p><ul><li>YSMU preparatory education page: AMD 1,200,000 a year for English-taught study (check the medicine fee)</li><li>Aggregator and scholarship sites give higher figures, such as AMD 1,500,000-2,600,000 for medicine</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-taught programmes</li></ul>' WHERE slug = 'armenia';
UPDATE countries SET why_title = 'Why study in Azerbaijan?', why_body = '<p>Azerbaijan is a fast-developing South Caucasus country with growing English-taught options at ADA University and state grants for international students.</p><ul><li>English-taught degrees at ADA University and others</li><li>Heydar Aliyev International Education Grant for international students</li><li>Low tuition and living costs</li><li>Baku as an energy and business hub</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-CIS students normally need a <strong>student visa</strong> for courses over 90 days, usually requested with an acceptance letter. ADA notes that applicants who cannot get an e-visa may be able to get a visa on arrival at Baku airport with a university letter.</p><ul><li>Acceptance letter from the university</li><li>Passport, photographs and proof of funds</li><li>Apply at an Azerbaijani embassy or consulate, or via e-visa where eligible</li><li>Students generally cannot work on a student visa (sources conflict on holiday work)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Azerbaijani embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. ADA''s late deadline for 2026 was 1 July, with an early scholarship deadline of 8 April.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Motivation letter and references</li><li>SAT or entrance test at some universities</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Third-party guides give typical ranges; check each university''s fee page.</p><ul><li>Tuition: roughly US$1,000-$5,000 a year at state universities (guide range; private universities such as ADA cost more)</li><li>ADA merit scholarships reported at 25%-50% tuition reduction</li><li>Living costs: about US$400-$800 a month (guide range)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 6.0 or equivalent for English-taught programmes</li></ul>' WHERE slug = 'azerbaijan';
UPDATE countries SET why_title = 'Why study in Bahrain?', why_body = '<p>Bahrain is a compact Gulf hub with English-medium private and public universities, strengths in finance, business and medicine (RCSI Bahrain), and an open, expatriate-friendly society.</p><ul><li>English-medium programmes</li><li>Gulf financial centre with strong banking</li><li>International campuses such as RCSI Bahrain</li><li>Safe, welcoming environment</li></ul>', visa_title = 'Student residence permit', visa_body = '<p>The university usually sponsors and submits the <strong>student residence permit</strong> to the National Passport and Residence Authority (NPRA). The permit covers study only.</p><ul><li>Admission letter and sponsorship by the institution</li><li>Passport, photographs and medical test</li><li>Fees reported: BHD 5 application fee with BHD 30-60 issuance or renewal (sources differ)</li><li>Permit length varies: some sources report one year renewable, others five years for local institutions</li><li>Processing can take two months or longer (RCSI Bahrain)</li><li>Students cannot work unless they switch to a work permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official NPRA and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance exam for some programmes</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs vary by institution.</p><ul><li>University of Bahrain: BHD 80 per credit hour for non-Bahraini undergraduates (2026), or about BHD 10,240 for a 128-credit degree</li><li>Private universities: check each university</li><li>Living costs: about US$600-$1,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent; some programmes are in Arabic</li></ul>' WHERE slug = 'bahrain';
UPDATE countries SET why_title = 'Why study in Kuwait?', why_body = '<p>Kuwait is a wealthy Gulf state with English-medium private universities in business, engineering and design, though the main public university prioritises Kuwaiti and GCC nationals.</p><ul><li>English-medium programmes at private universities</li><li>Gulf economy with strong energy and finance sectors</li><li>Modern campuses</li><li>Centre for Arabic language and culture study</li></ul>', visa_title = 'Student residence requirements', visa_body = '<p>Visas and residence are issued by the General Department of Residency (Ministry of Interior). The university usually acts as the sponsor and applies for the <strong>student residence</strong> for you.</p><ul><li>Admission letter from a recognised institution</li><li>Proof of finances for tuition and living costs</li><li>Passport, photographs and matching identity details</li><li>After arrival: medical checks, fingerprints and Civil ID</li><li>Student residence is reported as valid for 1 year and renewable while enrolled</li><li>No work right and no post-study route or path to permanent residence (official pages)</li><li>New executive regulations for the residence law were issued in late 2025, so requirements may have changed</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Ministry of Interior and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Kuwait University mostly admits Kuwaitis and GCC nationals and takes non-Kuwaitis only into remaining places. Private universities admit international applicants directly.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance exam for some programmes</li><li>Passport copy and photographs</li><li>Kuwait University admission fee reported at KWD 10 (2026)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition figures were not found in search results.</p><ul><li>Private universities: check each university, as fees are set per credit hour</li><li>Living costs: about US$700-$1,200 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent; some programmes are in Arabic</li></ul>' WHERE slug = 'kuwait';
COMMIT;
